//! Upstream OTLP protobuf bindings and conversion into canonical trace types.
//! Generated by prost from pinned official sources (see docs/OTLP_PROTOBUF.md).

mod convert;

pub use convert::{
    convert_span, decode_export, decode_export_report, DecodeError, DecodeReport, IdField,
    SpanError, TimeField,
};

pub mod opentelemetry {
    pub mod proto {
        pub mod common {
            pub mod v1 {
                include!(concat!(
                    env!("OUT_DIR"),
                    "/opentelemetry.proto.common.v1.rs"
                ));
            }
        }
        pub mod resource {
            pub mod v1 {
                include!(concat!(
                    env!("OUT_DIR"),
                    "/opentelemetry.proto.resource.v1.rs"
                ));
            }
        }
        pub mod trace {
            pub mod v1 {
                include!(concat!(env!("OUT_DIR"), "/opentelemetry.proto.trace.v1.rs"));
            }
        }
        pub mod collector {
            pub mod trace {
                pub mod v1 {
                    include!(concat!(
                        env!("OUT_DIR"),
                        "/opentelemetry.proto.collector.trace.v1.rs"
                    ));
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::opentelemetry::proto::collector::trace::v1::ExportTraceServiceRequest;
    use prost::Message;

    #[test]
    fn official_export_trace_service_request_roundtrip() {
        let req = ExportTraceServiceRequest::default();
        let encoded = req.encode_to_vec();
        let decoded = ExportTraceServiceRequest::decode(encoded.as_slice()).unwrap();
        assert_eq!(decoded.resource_spans.len(), 0);
    }
}
